// Regenerates src/data/lessonIndex.generated.ts from the full curriculum.
// Run with: npm run generate:index   (also runs automatically before build)
import { writeFileSync } from 'fs';
import path from 'path';
import { LESSONS } from '../src/data/curriculum';
import { toLessonSummary } from '../src/data/catalog';

export function renderLessonIndex(): string {
  const summaries = LESSONS.map(toLessonSummary);
  return [
    '// AUTO-GENERATED by scripts/generate-lesson-index.ts from src/data/curriculum.ts.',
    '// Do not edit by hand: run `npm run generate:index` after changing lessons.',
    "import type { LessonSummary } from './catalog';",
    '',
    `export const LESSON_INDEX: LessonSummary[] = ${JSON.stringify(summaries, null, 2)};`,
    '',
  ].join('\n');
}

const isMain = process.argv[1] && path.resolve(process.argv[1]) === path.resolve(__filename);
if (isMain) {
  const out = path.join(__dirname, '..', 'src', 'data', 'lessonIndex.generated.ts');
  writeFileSync(out, renderLessonIndex());
  console.log(`Wrote ${LESSONS.length} lesson summaries to ${path.relative(process.cwd(), out)}`);
}
